export type Language='en'|'it';
/** English is the product default, independently of the browser locale. */
let language:Language='en';
try{if(localStorage.getItem('bjlab.language')==='it')language='it'}catch{}
export const getLanguage=()=>language;
export function setLanguage(value:Language){language=value;try{localStorage.setItem('bjlab.language',value)}catch{};if(typeof document!=='undefined')document.documentElement.lang=value;if(typeof window!=='undefined')window.dispatchEvent(new Event('bjlab:language'))}
