for(const [en,it] of Object.entries({...visionItalian,...liveItalian,...versionOneItalian,...reliabilityItalian})){primary.set(it,en);secondary.set(en,it)}
export function t(text:string):string{
 const raw=text.trim();
 let translated=language==='en'?(primary.get(raw)||raw):(secondary.get(raw)||raw);
 const dynamic: [RegExp,string,string][]=[
  [/^(\d+) mazzi · (\d+) carte osservate$/,'$1 decks · $2 observed cards','$1 mazzi · $2 carte osservate'],
  [/^([\d.]+) mazzi fisici rimasti$/,'$1 physical decks remaining','$1 mazzi fisici rimasti'],
  [/^Round (\d+) · unità di puntata$/,'Round $1 · wager units','Round $1 · unità di puntata'],
  [/^Profitto ([\d.+-]+)$/,'Profit $1','Profitto $1'],
  [/^Puntata ([\d.+-]+)$/,'Wager $1','Puntata $1'],
  [/^(\d+) mazzi$/,'$1 decks','$1 mazzi'],
  [/^Frame video (\d+)$/,'Video image $1','Frame video $1'],
  [/^Eventi fino a questo frame \((\d+)\)$/,'Events up to this image ($1)','Eventi fino a questo frame ($1)'],
  [/^Una singola immagine viene confermata con ([\d—]+) aggiornamenti del tracker\. Il throughput è una misura di elaborazione, non una frequenza di acquisizione live\.$/,'One still image is confirmed with $1 tracker updates. Throughput measures processing, not live capture frequency.','Una singola immagine viene confermata con $1 aggiornamenti del tracker. Il throughput è una misura di elaborazione, non una frequenza di acquisizione live.'],
  [/^(\d+) frame saltati per campionamento\.$/,'$1 video images skipped by sampling.','$1 frame saltati per campionamento.'],
 ];
 if(language==='en')for(const [pattern,en] of dynamic)if(pattern.test(raw)){translated=raw.replace(pattern,en);break}
 if(language==='it'){
  translated=translated.replace(/^(\d+) decks · (\d+) observed cards$/,'$1 mazzi · $2 carte osservate')
   .replace(/^([\d.]+) physical decks remaining$/,'$1 mazzi fisici rimasti')
   .replace(/^Round (\d+) · wager units$/,'Round $1 · unità di puntata')
   .replace(/^Profit ([\d.+-]+)$/,'Profitto $1').replace(/^Wager ([\d.+-]+)$/,'Puntata $1');
 }
 if(language==='it'&&/^\d+ cards await stable visual evidence$/.test(raw))translated=raw.replace(' cards await stable visual evidence',' carte attendono evidenza video stabile');
 // Preserve separators around dynamic React text fragments.
 if(raw!==text)translated=text.slice(0,text.indexOf(raw))+translated+text.slice(text.indexOf(raw)+raw.length);
 return translated;
}
